SELECT f.id AS follow_id, m.id AS member_id, m.name, m.unique_id, m.profile_image FROM follow f JOIN member m ON m.id = f.member_id
AND f.target_id = #{memberId}
AND f.id < #{cursor}
ORDER BY f.id DESC LIMIT #{limit}

